    da: l.casella,
    nome_mittente: l.nome_mittente,
    a: CFG.modalita_test ? CFG.email_test : l.email,
    oggetto: `Re: ${oggettoBase}`,
    testo: riempi(corpo, valori),
    thread_id: l.thread_id,
    in_reply_to: ultimo.message_id || '',
    references: ids.join(' '),
    list_unsubscribe: l.casella,
    rif: l.lead_id,
  },
};

